#!/usr/bin/env node

/**
 * Benchmarks building each demo from source vs incrementally, with the libs pre-built either by
 * ng-packagr (`build-ng-packagr` targets) or by the Oxc/Rolldown-based `@angular/build:library`
 * builder (`build` targets).
 *
 * Demos:
 *   - app0:         one app with 5 big libs, a single entry point each (heavy TypeScript, few stylesheets)
 *   - entry-points: the apps generated by tools/generate-entry-point-libs.mjs, whose libs (feature libs
 *                   per app plus shared UI libs) are split into many secondary entry points, every
 *                   component with an SCSS stylesheet
 *
 * For each demo and mode it measures:
 *   - cold:           empty Nx cache, no dist output
 *   - lib-changed:    one file in one app's lib changed, caches populated by the previous runs
 *   - shared-changed: one file in a shared lib that every app depends on changed (entry-points demo only)
 *   - cache-hit:      nothing changed, everything replayed from the Nx cache
 *
 * Wall time, peak memory of the whole process tree and per-task timings (from the Nx profile)
 * are written to tmp/benchmark/results.json, and a Markdown summary to tmp/benchmark/summary.md
 * (also appended to the GitHub job summary when running in Actions).
 *
 * Usage: node tools/benchmark.mjs [--iterations=3] [--demos=app0,entry-points] [--modes=source,ng-packagr,library]
 */

import { spawn, execFileSync } from 'node:child_process';
import { appendFileSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync, existsSync } from 'node:fs';
import { join, relative } from 'node:path';

const ROOT = process.cwd();
const OUT_DIR = join(ROOT, 'tmp/benchmark');
const PROFILES_DIR = join(OUT_DIR, 'profiles');
const MEMORY_POLL_MS = 250;

const iterations = Number(
  process.argv.find((arg) => arg.startsWith('--iterations='))?.split('=')[1] ?? 3
);

if (!Number.isInteger(iterations) || iterations < 1) {
  console.error(`--iterations must be a positive integer, got "${iterations}"`);
  process.exit(1);
}

const NX_ENV = {
  NX_DAEMON: 'false',
  NX_NO_CLOUD: 'true',
  NX_TUI: 'false',
};

const DEMOS = {
  app0: {
    description: 'One app with 5 libs, a single entry point each and 311 components per lib with large, type-heavy TypeScript',
    apps: () => ['app0'],
    changedFiles: {
      'lib-changed': 'libs/app0/lib0/src/lib/child-0/sub-children/sub-child-0.component.ts',
    },
  },
  'entry-points': {
    description: describeEntryPointsDemo,
    apps: () => nxProjects('tag:type:app'),
    changedFiles: {
      'lib-changed': 'libs/app1/lib0/feature-0/src/lib/item-0.component.ts',
      'shared-changed': 'libs/shared/ui0/widget-0/src/lib/item-0.component.ts',
    },
  },
};

const MODES = {
  source: {
    label: 'From source',
    description: 'every app compiles all of its libs from source (`buildLibsFromSource: true`)',
    build: (apps) => ['run-many', '-t', 'build', '-p', apps.join(','), '--excludeTaskDependencies'],
  },
  'ng-packagr': {
    label: 'Incremental (ng-packagr)',
    description: 'libs built with ng-packagr (`@nx/angular:package`), the apps consume `dist` (`buildLibsFromSource: false`)',
    build: (apps) => ['run-many', '-t', 'build-ng-packagr', '-p', apps.join(',')],
  },
  library: {
    label: 'Incremental (@angular/build:library)',
    description: 'libs built with the Oxc/Rolldown-based `@angular/build:library`, the apps consume `dist` (`buildLibsFromSource: false`)',
    build: (apps) => ['run-many', '-t', 'build', '-p', apps.join(','), '--buildLibsFromSource=false'],
  },
};

function nxProjects(pattern) {
  const output = execFileSync('npx', ['nx', 'show', 'projects', '--projects', pattern, '--json'], {
    encoding: 'utf8',
    env: { ...process.env, ...NX_ENV },
  });
  return JSON.parse(output).sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
}

function describeEntryPointsDemo() {
  const apps = nxProjects('tag:type:app');
  const shared = nxProjects('tag:type:shared');
  const featureLibs = nxProjects('tag:demo:entry-points').length - apps.length - shared.length;
  const entryPoints = readdirSync(join(ROOT, 'libs/shared/ui0')).filter((name) => name.startsWith('widget-')).length + 1;
  return `${apps.length} apps with ${featureLibs} feature libs plus ${shared.length} shared UI libs that every app uses. Every lib is split into ${entryPoints} secondary entry points and every component has an inline SCSS stylesheet`;
}

filterByArg(DEMOS, 'demos');
filterByArg(MODES, 'modes');

function filterByArg(record, name) {
  const value = process.argv.find((arg) => arg.startsWith(`--${name}=`))?.split('=')[1];
  if (!value) return;
  for (const key of Object.keys(record)) {
    if (!value.split(',').includes(key)) delete record[key];
  }
  if (!Object.keys(record).length) throw new Error(`Nothing known in --${name}=${value}`);
}

const SCENARIOS = [
  { key: 'cold', label: 'Cold', setup: resetWorkspace },
  { key: 'lib-changed', label: 'One app lib changed', setup: changeFile },
  { key: 'shared-changed', label: 'One shared lib changed', setup: changeFile },
  { key: 'cache-hit', label: 'Nx cache hit', setup: () => {} },
];

const appliesTo = (scenario, demo) => !scenario.key.endsWith('-changed') || scenario.key in demo.changedFiles;

function resetWorkspace() {
  revertLibChanges();
  execFileSync('npx', ['nx', 'reset', '--onlyCache'], { stdio: 'ignore', env: { ...process.env, ...NX_ENV } });
  // ng-packagr keeps its own tsbuildinfo and bundle cache outside of Nx (disabled when CI=true)
  for (const dir of ['dist', '.angular/cache', 'tmp/out-tsc', 'node_modules/.cache/ng-packagr']) {
    rmSync(join(ROOT, dir), { recursive: true, force: true });
  }
}

const originalContents = new Map();

function changeFile(demo, scenario) {
  const file = join(ROOT, demo.changedFiles[scenario.key]);
  if (!originalContents.has(file)) originalContents.set(file, readFileSync(file, 'utf8'));
  appendFileSync(file, `\n// benchmark change ${Date.now()}\n`);
}

function revertLibChanges() {
  for (const [file, content] of originalContents) writeFileSync(file, content);
}

/** Sums the RSS (in bytes) of `rootPid` and all of its descendants. */
function processTreeRss(rootPid) {
  let output;
  try {
    output = execFileSync('ps', ['-A', '-o', 'pid=,ppid=,rss='], { encoding: 'utf8' });
  } catch {
    return 0;
  }
  const children = new Map();
  const rss = new Map();
  for (const line of output.trim().split('\n')) {
    const [pid, ppid, kb] = line.trim().split(/\s+/).map(Number);
    rss.set(pid, kb * 1024);
    if (!children.has(ppid)) children.set(ppid, []);
    children.get(ppid).push(pid);
  }
  let total = 0;
  const queue = [rootPid];
  while (queue.length) {
    const pid = queue.pop();
    total += rss.get(pid) ?? 0;
    queue.push(...(children.get(pid) ?? []));
  }
  return total;
}

function runNx(args, profilePath) {
  return new Promise((resolve, reject) => {
    const start = performance.now();
    const child = spawn('npx', ['nx', ...args, '--output-style=static'], {
      cwd: ROOT,
      // Nx resolves NX_PROFILE relative to the workspace root
      env: { ...process.env, ...NX_ENV, NX_PROFILE: relative(ROOT, profilePath) },
      stdio: ['ignore', 'inherit', 'inherit'],
    });
    let peakRss = 0;
    const poll = setInterval(() => {
      peakRss = Math.max(peakRss, processTreeRss(child.pid));
    }, MEMORY_POLL_MS);
    child.on('error', reject);
    child.on('exit', (code) => {
      clearInterval(poll);
      const durationMs = performance.now() - start;
      if (code !== 0) {
        reject(new Error(`nx ${args.join(' ')} exited with code ${code}`));
        return;
      }
      resolve({ durationMs, peakRss });
    });
  });
}

function readTasks(profilePath) {
  if (!existsSync(profilePath)) return [];
  return JSON.parse(readFileSync(profilePath, 'utf8'))
    .filter((event) => event.ph === 'X')
    .map((event) => ({ task: event.name, durationMs: event.dur / 1000, status: event.args?.status }));
}

async function main() {
  mkdirSync(PROFILES_DIR, { recursive: true });
  const runs = [];

  try {
    for (let iteration = 1; iteration <= iterations; iteration++) {
      for (const [demoKey, demo] of Object.entries(DEMOS)) {
        const apps = demo.apps();
        for (const [modeKey, mode] of Object.entries(MODES)) {
          for (const scenario of SCENARIOS.filter((scenario) => appliesTo(scenario, demo))) {
            scenario.setup(demo, scenario);
            const name = `${demoKey}-${modeKey}-${scenario.key}-${iteration}`;
            const profilePath = join(PROFILES_DIR, `${name}.json`);
            console.log(`\n=== [${iteration}/${iterations}] ${demoKey} · ${mode.label} · ${scenario.label} ===\n`);
            const { durationMs, peakRss } = await runNx(mode.build(apps), profilePath);
            const run = {
              iteration,
              demo: demoKey,
              mode: modeKey,
              scenario: scenario.key,
              durationMs,
              peakRss,
              tasks: readTasks(profilePath),
            };
            runs.push(run);
            console.log(`\n→ ${(durationMs / 1000).toFixed(1)}s, peak ${formatBytes(peakRss)}`);
          }
        }
      }
    }
  } finally {
    revertLibChanges();
  }

  const demos = Object.fromEntries(
    Object.entries(DEMOS).map(([key, demo]) => [
      key,
      {
        description: typeof demo.description === 'function' ? demo.description() : demo.description,
        apps: demo.apps(),
        changedFiles: demo.changedFiles,
      },
    ])
  );
  const results = {
    date: new Date().toISOString(),
    commit: execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim(),
    node: process.version,
    runner: process.env.RUNNER_NAME ?? null,
    nodeOptions: process.env.NODE_OPTIONS ?? null,
    ci: process.env.CI ?? null,
    iterations,
    demos,
    runs,
  };
  writeFileSync(join(OUT_DIR, 'results.json'), JSON.stringify(results, null, 2));

  const summary = renderSummary(results);
  writeFileSync(join(OUT_DIR, 'summary.md'), summary);
  if (process.env.GITHUB_STEP_SUMMARY) {
    appendFileSync(process.env.GITHUB_STEP_SUMMARY, summary);
  }
  console.log(`\n${summary}`);
}

function renderSummary({ commit, node, iterations, demos, runs, nodeOptions, ci }) {
  const lines = [
    '## Build benchmark: from source vs incremental (ng-packagr vs @angular/build:library)',
    '',
    `Commit \`${commit.slice(0, 8)}\` · Node ${node} · ${iterations} iteration(s) · \`NODE_OPTIONS=${nodeOptions ?? ''}\` · \`CI=${ci ?? ''}\``,
    '',
    ...Object.entries(MODES).map(([, mode]) => `- **${mode.label}**: ${mode.description}`),
    '',
    'Time and memory are the median across iterations (min–max in brackets). Memory is the peak RSS of the whole Nx process tree. "Lib tasks" and "App tasks" are the summed durations of the lib and app build tasks that actually ran (Nx runs up to 3 at once).',
  ];

  const seconds = (values) => stat(values, (s) => `${s.toFixed(1)}s`);
  const executed = (run) => run.tasks.filter((task) => !task.status?.includes('cache'));

  for (const [demoKey, { description, apps, changedFiles }] of Object.entries(demos)) {
    const isAppTask = (task) => apps.includes(task.task.split(':')[0]);
    const sumOf = (tasks) => tasks.reduce((sum, task) => sum + task.durationMs / 1000, 0);
    lines.push(
      '',
      `### ${demoKey}`,
      '',
      `${description}.`,
      '',
      ...Object.entries(changedFiles).map(
        ([key, file]) => `- "${SCENARIOS.find((s) => s.key === key).label}" edits \`${file}\``
      ),
      '',
      '| Scenario | Mode | Wall time | Peak memory | Lib tasks | App tasks | Tasks run / cached |',
      '| --- | --- | --- | --- | --- | --- | --- |'
    );
    for (const scenario of SCENARIOS) {
      for (const [modeKey, mode] of Object.entries(MODES)) {
        const matching = runs.filter((run) => run.demo === demoKey && run.mode === modeKey && run.scenario === scenario.key);
        if (!matching.length) continue;
        const libTime = matching.map((run) => sumOf(executed(run).filter((task) => !isAppTask(task))));
        const appTime = matching.map((run) => sumOf(executed(run).filter(isAppTask)));
        const tasks = matching[0]?.tasks ?? [];
        const cached = tasks.filter((task) => task.status?.includes('cache')).length;
        lines.push(
          `| ${scenario.label} | ${mode.label} | ${seconds(matching.map((run) => run.durationMs / 1000))} | ${stat(matching.map((run) => run.peakRss), formatBytes)} | ${libTime.some(Boolean) ? seconds(libTime) : '–'} | ${appTime.some(Boolean) ? seconds(appTime) : '–'} | ${tasks.length - cached} / ${cached} |`
        );
      }
    }
  }

  lines.push('', '<details><summary>Per-task timings (first iteration)</summary>', '');
  lines.push('| Demo | Scenario | Mode | Task | Duration | Status |', '| --- | --- | --- | --- | --- | --- |');
  for (const run of runs.filter((run) => run.iteration === 1)) {
    for (const task of run.tasks) {
      lines.push(
        `| ${run.demo} | ${SCENARIOS.find((s) => s.key === run.scenario).label} | ${MODES[run.mode].label} | \`${task.task}\` | ${(task.durationMs / 1000).toFixed(1)}s | ${task.status} |`
      );
    }
  }
  lines.push('', '</details>', '');
  return lines.join('\n');
}

function stat(values, format) {
  if (!values.length) return 'n/a';
  const sorted = [...values].sort((a, b) => a - b);
  const median = sorted[Math.floor(sorted.length / 2)];
  if (sorted.length === 1) return format(median);
  return `${format(median)} (${format(sorted[0])}–${format(sorted.at(-1))})`;
}

function formatBytes(bytes) {
  return `${(bytes / 1024 ** 3).toFixed(2)} GB`;
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
